#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

// Minimal JSON token helpers for judge input [[h0,h1,...]]
typedef struct { char* s; int pos; int len; } Tok;
static void skipWS(Tok* t) { while (t->pos < t->len && (t->s[t->pos] == ' ' || t->s[t->pos] == ',' || t->s[t->pos] == '\t' || t->s[t->pos] == '\n' || t->s[t->pos] == '\r')) t->pos++; }
static char* nextToken(Tok* t) {
    skipWS(t);
    if (t->pos >= t->len) return NULL;
    if (t->s[t->pos] == '[') {
        int start = t->pos;
        int depth = 0;
        while (t->pos < t->len) {
            char c = t->s[t->pos++];
            if (c == '[') depth++;
            else if (c == ']') { depth--; if (depth == 0) break; }
        }
        int toklen = t->pos - start;
        char* out = (char*)malloc(toklen + 1);
        strncpy(out, t->s + start, toklen);
        out[toklen] = '\0';
        return out;
    }
    return NULL;
}

static int* parse_int_array(Tok* t, int* out_size) {
    char* tok = nextToken(t);
    if (!tok) { *out_size = 0; return NULL; }
    int len = (int)strlen(tok);
    if (len <= 2) { free(tok); *out_size = 0; return NULL; }
    char* inner = (char*)malloc(len - 1);
    strncpy(inner, tok + 1, len - 2);
    inner[len - 2] = '\0';
    free(tok);

    int count = 0;
    for (int i = 0; inner[i]; ++i) if (inner[i] == ',') count++;
    count = count + (strlen(inner) ? 1 : 0);
    int* arr = (int*)malloc(sizeof(int) * count);
    Tok t2 = { inner, 0, (int)strlen(inner) };
    for (int i = 0; i < count; ++i) {
        skipWS(&t2);
        int start = t2.pos;
        while (t2.pos < t2.len && t2.s[t2.pos] != ',') t2.pos++;
        int toklen = t2.pos - start;
        char tmp[32];
        if (toklen >= (int)sizeof(tmp)) toklen = (int)sizeof(tmp) - 1;
        strncpy(tmp, t2.s + start, toklen);
        tmp[toklen] = '\0';
        arr[i] = atoi(tmp);
        if (t2.pos < t2.len && t2.s[t2.pos] == ',') t2.pos++;
    }
    free(inner);
    *out_size = count;
    return arr;
}

// Two-pointer O(n) solution
int maxArea(int* height, int heightSize) {
    int i = 0, j = heightSize - 1;
    long long best = 0;
    while (i < j) {
        int h = height[i] < height[j] ? height[i] : height[j];
        long long area = (long long)h * (j - i);
        if (area > best) best = area;
        if (height[i] < height[j]) ++i; else --j;
    }
    return (int)best;
}

int main(void) {
    char *line = NULL; size_t cap = 0; ssize_t nread = getline(&line, &cap, stdin);
    if (nread <= 0) { if (line) free(line); return 0; }
    while (nread > 0 && (line[nread-1] == '\n' || line[nread-1] == '\r')) line[--nread] = '\0';
    Tok tok = { line, 0, (int)strlen(line) };
    int n = 0;
    int* height = parse_int_array(&tok, &n);
    int result = 0;
    if (height && n >= 2) result = maxArea(height, n);
    printf("%d\n", result);
    if (height) free(height);
    free(line);
    return 0;
}

